def gen(rng):
    def make(n, lo, hi, deep):
        val = [rng.randint(lo, hi)]
        L = [-1]
        R = [-1]
        slots = [(0, 0), (0, 1)]
        for v in range(1, n):
            if rng.random() < deep:
                k = len(slots) - 1
            else:
                k = rng.randrange(len(slots))
            slots[k], slots[-1] = slots[-1], slots[k]
            p, side = slots.pop()
            val.append(rng.randint(lo, hi))
            L.append(-1)
            R.append(-1)
            if side == 0:
                L[p] = v
            else:
                R[p] = v
            slots.append((v, 0))
            slots.append((v, 1))
        return val, L, R

    def serialize(val, L, R):
        toks = [str(val[0])]
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            for c in (L[u], R[u]):
                if c == -1:
                    toks.append('null')
                else:
                    toks.append(str(val[c]))
                    q.append(c)
        while toks[-1] == 'null':
            toks.pop()
        return ' '.join(toks)

    def leaf_sums(val, L, R):
        sums = []
        stack = [(0, val[0])]
        while stack:
            u, s = stack.pop()
            if L[u] == -1 and R[u] == -1:
                sums.append(s)
            for c in (L[u], R[u]):
                if c != -1:
                    stack.append((c, s + val[c]))
        return sums

    def case(n, lo, hi, deep, hit=True):
        val, L, R = make(n, lo, hi, deep)
        sums = leaf_sums(val, L, R)
        if hit and rng.random() < 0.85:
            t = rng.choice(sums)
        else:
            t = rng.randint(-20, 20)
        return serialize(val, L, R) + '\n' + str(t)

    tests = ['5\n5', '5\n6', '1 2\n1', '1 2\n3', '1 null 2\n3', '1 2 null\n3', '0 0 0\n0', '-3 -2 -1\n-5',
             '7 3 5 4 1 2 null\n14', '1000 1000 1000\n2000']
    for n in (2, 3, 4, 5, 7, 9, 12):
        for (lo, hi) in ((-1, 1), (0, 3), (-10, 10)):
            tests.append(case(n, lo, hi, rng.choice([0.0, 0.5, 0.9])))
    for _ in range(4):
        tests.append(case(11, 0, 1, 0.0, True))
    # large cases
    tests.append(case(2000, -1000, 1000, 0.0))
    tests.append(case(2000, -1000, 1000, 1.0))
    tests.append(case(2000, 0, 0, 0.0, False).rsplit('\n', 1)[0] + '\n0')
    tests.append(case(2000, -2, 2, 0.6))
    tests.append(case(600, 0, 0, 0.99, False).rsplit('\n', 1)[0] + '\n0')
    return tests
